window.FILM_WORK_PROMPTS={"work_id":"src-81330ba76551a388","records":[{"work_id":"src-81330ba76551a388","frame_id":"FG-7f49a6184c7389f2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6006.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"一名梳着高发髻的人物位于画面中央，背景是模糊的深色树林与天空，人物神情平静，直视前方。","analysis":"画面采用中心构图，人物头部及肩部占据画面主要位置，背景树木虚化。光线从上方投射，照亮人物面部，形成柔和的明暗过渡。整体色调偏冷，背景深绿与人物肤色形成对比，视觉焦点集中在人物面部。","prompt":"低分辨率画面，中心构图。一名梳着高发髻的人物位于画面正中，仅可见头部及肩部，面部朝向正前方，神情平静。背景为虚化的深色树林与天空，环境占比大。光线从上方投射，照亮人物面部，形成柔和的明暗过渡。整体色调偏冷，背景深绿与人物肤色形成对比，视觉焦点集中在人物面部。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:49:01-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6006.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-c38eb303b1e8a333","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-cd11d4772288c372","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6016.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"人物头部位于画面中央，面部被交叉的亮白色光带遮挡，背景为大面积模糊的棕褐色垂直纹理，整体色调偏暖且昏暗。","analysis":"构图采用中心对称，人物头部占据画面核心位置，仅可见头顶发髻及两侧发饰，面部完全被X形光带覆盖。背景为失焦的棕褐色块，呈现出类似枯草或芦苇的垂直线条感。光线集中在人物面部前方，形成强烈的白色高光与彩虹色散，与周围暗部形成高对比度，营造出神秘且压抑的视觉氛围。","prompt":"低分辨率画面，中心构图。一名人物头部位于正中，深色头发梳成发髻，两侧有浅色发饰。面部被两道交叉的亮白色光带完全遮挡，光带中心呈现彩虹色散效果，亮度极高。背景为大面积模糊的棕褐色垂直纹理，类似枯草或芦苇丛，占据画面绝大部分空间。整体色调昏暗，以棕色和黑色为主，仅中心光带为亮白色。人物仅露出头顶部分，身体不可见。画面具有强烈的明暗对比，光晕效果明显，营造出一种神秘、压抑且带有超自然色彩的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:49:07-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6016.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-76cc7d92d2fb8504","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-66de5b68f9dfeeaa","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6026.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"画面主体为一张被深色物质覆盖的人脸，占据画面中心。背景昏暗模糊，左侧有垂直的亮色条状物，右侧有模糊的亮斑，整体环境幽暗压抑。","analysis":"构图极度紧凑，人物面部占据画面约80%面积，仅可见头部及少许肩部轮廓。视角平视，光线从左侧微弱打入，形成强烈的明暗对比。面部覆盖着粗糙的深褐色物质，质感厚重，右侧脸颊和额头有零星的灰白色斑块。背景虚化严重，仅能辨识出左侧的垂直亮线和右侧的模糊光点，色彩以深褐、黑灰为主，局部有暖黄色调。","prompt":"低分辨率画面，主体为一张被深褐色粗糙物质覆盖的人脸，占据画面中心大部分区域。人物头部及少许肩部可见，面部质感厚重，右侧脸颊和额头分布着灰白色斑块，双眼在阴影中隐约可见。背景极度昏暗且虚化，左侧有垂直的暖黄色亮色条状物，右侧有模糊的亮斑。光线从左侧微弱照射，形成强烈的明暗对比，整体色调为深褐、黑灰与暖黄，氛围压抑，无清晰五官细节。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:49:14-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6026.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-a3f5a1e4dd8ab1bf","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-d5e0284b2cba7cfa","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6036.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"昏暗室内，左侧一名束发男子与一名幼童并排而坐，右侧一名蒙面人物跪坐，两人隔着一根粗大立柱相对，地面呈深色。","analysis":"画面采用横向构图，中间一根巨大的垂直立柱将空间分割。左侧人物与幼童呈侧面坐姿，右侧人物正面跪坐，人物在画面中占比适中。光线从左侧射入，照亮左侧人物面部与肩部，右侧人物处于阴影中，仅轮廓可见。整体色调偏暗，明暗对比强烈，营造出压抑的视觉氛围。","prompt":"昏暗的室内场景，画面中央有一根粗大的垂直立柱。左侧一名束发男子身穿深色和服，侧身坐着，身旁依偎着一名幼童。右侧一名身穿深色衣物、面部被布料蒙住的人物跪坐在地，双手置于膝前。左侧光源照亮了男子的侧脸和肩部，右侧人物大部分处于阴影中。地面为深色，背景是平整的墙壁，整体色调低沉，明暗对比分明，呈现出一种静谧而紧张的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:49:20-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6036.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-6280c88822dc3f81","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-5dd9c8c1070563bd","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6046.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"雪原中，一名戴斗笠的深色衣着人物站立在木制雪橇旁，手扶框架，周围是大片白色雪地。","analysis":"画面采用远景构图，人物与雪橇位于画面右侧，占据约三分之一宽度，左侧留有大面积白色负空间。人物全身可见，呈站立姿态，身体轮廓为深色剪影，头部斗笠呈三角形。雪橇为深色木质结构，带有滑轨。整体光线均匀漫射，无明显阴影，色彩以黑白灰为主，对比度较低，呈现出寒冷、空旷的视觉氛围。","prompt":"低分辨率画面，广阔平坦的白色雪原背景，画面右侧站立一名身穿深色长袍、头戴宽边斗笠的人物，人物全身可见，呈站立姿态，双手扶着身旁的木制雪橇框架。雪橇为深色木质结构，底部带有滑轨，停在雪地上。人物与雪橇在画面中占比适中，左侧留有大面积空白雪地。光线柔和均匀，无强烈阴影，整体色调为黑白灰，呈现出寒冷、寂静的雪景氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:49:26-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6046.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-a0667cfb89e64835","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-e93228c9dc1d79a4","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6005.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"画面主体为传统日式建筑，上方是大面积深色瓦顶，下方是白墙黑柱。前景一人背对镜头站立，门廊深处另一人面向镜头站立。","analysis":"构图呈横向展开，上方约三分之一被深色瓦顶占据，下方为建筑立面。前景人物仅见背部及头部轮廓，身形较大；远处人物位于门廊阴影中，身形较小，呈站立姿态。光线自然，白墙与深色木结构形成明暗对比，整体色调偏冷且对比度适中。","prompt":"低分辨率画面，展示传统日式建筑外观。画面上方约三分之一被深灰色瓦片屋顶覆盖，瓦片纹理清晰。下方是白墙与深色木质框架结构，右侧可见木格窗。前景中央偏左有一人物背影，身穿深色衣物，头部轮廓清晰，占据画面下方较大比例。在建筑门廊深处的阴影中，站立着另一人物，身穿蓝色上衣，身形较小，面向镜头方向。整体光线柔和，白墙明亮，门廊内部较暗，形成明显的明暗层次。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T15:13:54+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6005.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-ada61836364f3138","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-80db006dff771422","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6015.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"一名深色头发的人物上半身位于画面中央，面部被一道斜向的明亮光带遮挡。背景是大面积模糊的蓝灰色调，散布着散乱的白色光斑。","analysis":"人物头部与肩部占据画面中心，背景环境占比约七成。视角接近平视，人物面部大部分被一道强烈的白色斜向光带覆盖，仅露出部分眉眼轮廓。背景呈现失焦的蓝灰色，带有明显的圆形光斑，整体光线对比强烈，前景光带与暗色人物形成反差。","prompt":"低分辨率画面，一名深色头发的人物上半身位于画面正中，身穿深色衣物。一道强烈的白色斜向光带从画面左下方向右上方延伸，横穿并遮挡了人物的面部区域。背景是大面积失焦的蓝灰色调，分布着许多模糊的白色圆形光斑。人物轮廓在暗色中显现，与明亮的背景光斑形成对比，整体色调偏冷，具有朦胧的视觉质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T15:14:04+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6015.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-e02ce0dd76a6dd65","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-47204957ed4c948d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6027.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"画面主体为一名戴着编织宽檐帽的人物面部特写，占据画面右侧及中央大部分区域。背景为极度虚化的暗绿色与褐色斑驳色块，环境细节不可辨，整体呈现昏暗的户外自然光氛围。","analysis":"构图采用极近距离的局部取景，人物面部占据画面约80%面积，头顶的编织帽檐横切画面顶部。人物身体仅可见面部及帽檐，无其他肢体可见。视角接近平视，光线从画面左侧射入，在面部形成强烈的明暗对比，左脸受光，右脸及眼窝陷入深重阴影。色彩以低饱和度的土黄、深褐与暗绿为主，光色层次集中在面部受光区的暖色调与背景冷暗色调的对比上。","prompt":"低分辨率写实风格画面，主体为一名戴着深色编织宽檐帽的人物面部特写。人物面部占据画面右侧及中央，帽檐横切顶部，编织纹理粗糙可见。面部皮肤呈现土黄色调，左侧受光，右侧及眼窝处于深重阴影中，形成强烈明暗对比。背景为极度虚化的暗绿色与褐色斑驳色块，无具体环境细节。光线从左侧射入，色调低沉，以土黄、深褐与暗绿为主，画面质感粗糙，无清晰五官细节，仅保留大轮廓与光影色块。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T15:14:18+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6027.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-82c0eff7c2fe4894","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-7f1c559fd638f19e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6037.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"昏暗烟雾笼罩的户外场景，一排人物剪影站立在带栏杆的高架栈道上，前景为大片深色植被，背景右侧可见模糊的建筑物轮廓。","analysis":"画面采用横向构图，高架栈道横贯画面中部，将空间分为上下两部分。人物呈剪影状站立，仅能辨识出大致的身体轮廓和头部形状，具体面部与衣着细节不可见。环境光线极暗，整体色调偏冷灰，背景烟雾增加了画面的朦胧感。前景植被占据画面下方约三分之一，形成深色遮挡。","prompt":"昏暗的户外夜景，浓重的烟雾弥漫在空气中。画面中部是一条横向延伸的高架木制栈道，带有垂直栏杆。栈道上站立着约七八个人物剪影，他们呈站立姿态，身体轮廓在烟雾中显得模糊。前景是大片深黑色的杂草或灌木丛，占据了画面下方的三分之一区域，遮挡了栈道底部。背景右侧隐约可见一座建筑物的轮廓，有微弱的亮区。整体画面色调灰暗，对比度低，呈现出一种压抑、神秘的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T15:14:24+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6037.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-f9d106fd582b9d6a","origin":"visual"},{"work_id":"src-81330ba76551a388","frame_id":"FG-d84ae928545d4bfa","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6047.jpg","source_page":"https://film-grab.com/2016/12/12/lone-wolf-and-cub-white-heaven-in-hell/","scene":"一位白发白须老者面部占据画面主体，右眼佩戴黑色眼罩，背景为模糊的浅色区域，左侧边缘可见深色衣物轮廓。","analysis":"画面采用极近距离构图，人物面部占据绝大部分空间，仅可见头部及少许肩部。视角接近平视，光线从右上方照射，在面部形成明暗对比，白发与白须呈现蓬松质感，黑色眼罩与浅色背景形成强烈反差，整体色调偏暖。","prompt":"一位满脸白胡子的老者面部特写，占据画面中心，右眼佩戴黑色圆形眼罩，细黑带子斜跨额头。人物拥有浓密蓬松的白发和长白胡须，面部皮肤纹理粗糙，眼神锐利。背景为模糊的浅灰白色，左侧边缘有深色衣物色块遮挡。光线从右上方投射，照亮面部右侧，左侧处于阴影中，整体色调偏暖，画面清晰度较低，呈现粗糙的颗粒感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T15:14:30+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/lonewolf6047.jpg","observed_dimensions":[500,211],"source_thumbnail_dimensions":[500,211],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-49e379b8400fe221","origin":"visual"}]};